  for(const value of [0,-0,1e-8,-2.345e-12,1.234e24,Number.MIN_VALUE,.24]){
   const text=pdfNumber(value);expect(text).not.toMatch(/[eE]/);expect(Number(text)).toBe(value===0?0:value);
  }
